#!/bin/bash

# Required parameters:
# @raycast.schemaVersion 1
# @raycast.title Stack Into Right Column
# @raycast.mode silent
# @raycast.packageName Striple

# Optional parameters:
# @raycast.icon 📥
# @raycast.description Stack Into Right Column. Runs: striple stack-right

# Generated by generate.sh. Do not edit: change the list in generate.sh and run it again.

cmd="stack-right"

find_cli() {
  command -v striple 2>/dev/null && return
  # Raycast does not load your shell profile, so also look in the usual places.
  for p in "$HOME/.local/bin/striple" /Applications/Striple.app/Contents/Helpers/striple; do
    if [ -x "$p" ]; then echo "$p"; return; fi
  done
}

cli="$(find_cli)"
if [ -z "$cli" ]; then
  # No CLI: the URL scheme runs the same command (and opens Striple if needed).
  open -g "striple://$cmd"
  exit
fi
out="$("$cli" "$cmd" 2>&1)"
status=$?
if [ "$status" -ne 3 ]; then
  [ -z "$out" ] || echo "$out"
  exit "$status"
fi
# Exit code 3: Striple is not running. The URL opens Striple and runs the command.
open -g "striple://$cmd"
